// Tipos de import
// Logo
// É a versão completa: ícone (mark) + wordmark (texto “PLANLY”) lado a lado.
// Use em header, footer, páginas de marketing — quando há espaço e você quer máximo reconhecimento de marca.

// LogoIcon
// É só o ícone (o símbolo).
// Use onde o espaço é pequeno ou quadrado: favicon, avatar, botão, splash, mobile tab, badge…
// Mais neutro e funciona bem em componentes compactos.

// LogoStroke
// É a variante contornada (stroke) do ícone/wordmark — sem preenchimento, apenas traços.
// Visual mais leve/minimal; bom sobre fundos muito chapados ou quando quer um look “outline”.
// Atenção: em tamanhos muito pequenos, o traço pode “sumir”; aumente strokeWidth.

//<Logo className="text-white" />
// <LogoIcon className="h-8" uniColor={false} />
// <Logo uniColor withShadow className="text-violet-600" />

// Cor: todas usam currentColor, então text-* do Tailwind controla a cor.

// Tamanho: defina pela altura (h-6, h-8…), o w-auto mantém a proporção.

// Stroke: se ficar fino demais, ajuste via strokeWidth={1.5|2}.

// // sólido (usa currentColor)
// <LogoIcon className="h-8 text-foreground" />

// // só contorno (meio transparente)
// <LogoStroke className="h-8 text-white" strokeWidth={2} />

// // sólido + borda
// <PlanlyMark className="h-8 text-violet-600" variant="fill+stroke" strokeWidth={1.5} />
